          unprocessed == other.unprocessed &&
          processing == other.processing &&
          searchable == other.searchable &&
          needsAttention == other.needsAttention;
}

/// 录音状态，契约第 3 节「录音」行。
enum RecordingState {
  idle,
  preparing,
  recording,
  paused,
  stopping,
